def minMaxDiff(nums, p):
    if p == 0:
        return 0
    a = sorted(nums)
    n = len(a)

    def pairs(d):
        cnt = 0
        i = 0
        while i + 1 < n:
            if a[i + 1] - a[i] <= d:
                cnt += 1
                i += 2
            else:
                i += 1
        return cnt

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs(mid) >= p:
            hi = mid
        else:
            lo = mid + 1
    return lo
